@namespace sv_10bfae382c55410eb1802d716e7f5877.Components.Pages.Catalog

<div class="product-card" @onclick="HandleCardClick" style="border:1px solid #ddd;border-radius:8px;padding:1rem;cursor:pointer;display:flex;flex-direction:column;gap:0.5rem;">
    <div class="product-image-placeholder" style="background:#f0f0f0;height:150px;display:flex;align-items:center;justify-content:center;border-radius:4px;">
        <span style="color:#999;">@Product.Name</span>
    </div>
    <h4 style="margin:0;">@Product.Name</h4>
    <p style="margin:0;font-weight:bold;color:#2a7ae2;">@Product.Price.ToString("C")</p>
    <span>@GetStarRating(Product.Rating)</span>
    @if (!Product.InStock)
    {
        <span style="background:#dc3545;color:white;padding:2px 8px;border-radius:4px;font-size:0.8rem;width:fit-content;">Out of Stock</span>
    }
    <button disabled="@(!Product.InStock)" @onclick="HandleAddToCart" @onclick:stopPropagation="true"
            style="padding:0.5rem;border:none;border-radius:4px;background:@(Product.InStock ? "#28a745" : "#ccc");color:white;cursor:@(Product.InStock ? "pointer" : "not-allowed");">
        Add to Cart
    </button>
</div>

@code {
    [Parameter, EditorRequired]
    public Product Product { get; set; } = default!;

    [Parameter]
    public EventCallback<Product> OnSelected { get; set; }

    [Parameter]
    public EventCallback<Product> OnAddToCart { get; set; }

    private async Task HandleCardClick()
    {
        await OnSelected.InvokeAsync(Product);
    }

    private async Task HandleAddToCart()
    {
        if (Product.InStock)
        {
            await OnAddToCart.InvokeAsync(Product);
        }
    }

    private static string GetStarRating(double rating)
    {
        int filled = (int)Math.Round(rating);
        return new string('★', filled) + new string('☆', 5 - filled);
    }
}

@namespace sv_10bfae382c55410eb1802d716e7f5877.Components.Pages.Catalog

<div class="product-grid" style="display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:1rem;">
    @foreach (var product in Products)
    {
        <ProductCard Product="product" OnSelected="OnProductSelected" OnAddToCart="OnAddToCart" />
    }
</div>

@code {
    [Parameter, EditorRequired]
    public List<Product> Products { get; set; } = [];

    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    [Parameter]
    public EventCallback<Product> OnAddToCart { get; set; }
}

@namespace sv_10bfae382c55410eb1802d716e7f5877.Components.Pages.Catalog

<aside style="padding:1rem;border-right:1px solid #ddd;">
    <h3>Filters</h3>

    <div style="margin-bottom:1rem;">
        <h4>Categories</h4>
        @foreach (var category in Categories)
        {
            <label style="display:block;margin-bottom:0.25rem;">
                <input type="checkbox" checked="@IsSelected(category)" @onchange="e => ToggleCategory(category, (bool)e.Value!)" />
                @category
            </label>
        }
    </div>

    <div style="margin-bottom:1rem;">
        <h4>Price Range</h4>
        <label style="display:block;margin-bottom:0.25rem;">
            Min:
            <input type="number" step="0.01" min="0" value="@_minPrice" @onchange="e => _minPrice = ParseDecimal(e.Value)" style="width:100%;" />
        </label>
        <label style="display:block;margin-bottom:0.25rem;">
            Max:
            <input type="number" step="0.01" min="0" value="@_maxPrice" @onchange="e => _maxPrice = ParseDecimal(e.Value)" style="width:100%;" />
        </label>
    </div>

    <div style="margin-bottom:1rem;">
        <label>
            <input type="checkbox" checked="@_inStockOnly" @onchange="e => _inStockOnly = (bool)e.Value!" />
            In Stock Only
        </label>
    </div>

    <div style="display:flex;flex-direction:column;gap:0.5rem;">
        <button @onclick="ApplyFilters" style="padding:0.5rem;background:#2a7ae2;color:white;border:none;border-radius:4px;cursor:pointer;">
            Apply Filters
        </button>
        <button @onclick="ClearFilters" style="padding:0.5rem;background:#6c757d;color:white;border:none;border-radius:4px;cursor:pointer;">
            Clear Filters
        </button>
    </div>
</aside>

@code {
    [Parameter, EditorRequired]
    public List<string> Categories { get; set; } = [];

    [Parameter]
    public EventCallback<ProductFilter> OnFilterApplied { get; set; }

    [Parameter]
    public EventCallback OnFilterCleared { get; set; }

    private List<string> _selectedCategories = [];
    private decimal? _minPrice;
    private decimal? _maxPrice;
    private bool _inStockOnly;

    private bool IsSelected(string category) => _selectedCategories.Contains(category);

    private void ToggleCategory(string category, bool selected)
    {
        if (selected)
            _selectedCategories.Add(category);
        else
            _selectedCategories.Remove(category);
    }

    private async Task ApplyFilters()
    {
        var filter = new ProductFilter(
            _selectedCategories.Count > 0 ? new List<string>(_selectedCategories) : null,
            _minPrice,
            _maxPrice,
            _inStockOnly
        );
        await OnFilterApplied.InvokeAsync(filter);
    }

    private async Task ClearFilters()
    {
        _selectedCategories = [];
        _minPrice = null;
        _maxPrice = null;
        _inStockOnly = false;
        await OnFilterCleared.InvokeAsync();
    }

    private static decimal? ParseDecimal(object? value)
    {
        if (value is null || string.IsNullOrWhiteSpace(value.ToString()))
            return null;
        return decimal.TryParse(value.ToString(), out var result) ? result : null;
    }
}

@namespace sv_10bfae382c55410eb1802d716e7f5877.Components.Pages.Catalog

<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:1rem;padding:0.5rem 0;border-bottom:1px solid #eee;">
    <div>
        <label>
            Sort by:
            <select value="@SortBy" @onchange="HandleSortChanged" style="padding:0.25rem 0.5rem;border-radius:4px;border:1px solid #ccc;">
                <option value="price_asc">Price: Low to High</option>
                <option value="price_desc">Price: High to Low</option>
                <option value="name_asc">Name: A-Z</option>
                <option value="rating_desc">Rating: Highest</option>
            </select>
        </label>
    </div>
    <div>
        @if (TotalCount > 0)
        {
            var start = (Page - 1) * PageSize + 1;
            var end = Math.Min(Page * PageSize, TotalCount);
            <span>Showing @start–@end of @TotalCount products</span>
        }
    </div>
</div>

@code {
    [Parameter]
    public string SortBy { get; set; } = "price_asc";

    [Parameter]
    public int TotalCount { get; set; }

    [Parameter]
    public int Page { get; set; }

    [Parameter]
    public int PageSize { get; set; }

    [Parameter]
    public EventCallback<string> OnSortChanged { get; set; }

    private async Task HandleSortChanged(ChangeEventArgs e)
    {
        await OnSortChanged.InvokeAsync(e.Value?.ToString() ?? "price_asc");
    }
}

@namespace sv_10bfae382c55410eb1802d716e7f5877.Components.Pages.Catalog

@{
    var totalPages = (int)Math.Ceiling((double)TotalCount / PageSize);
}

@if (totalPages > 1)
{
    <nav style="display:flex;justify-content:center;gap:0.25rem;margin-top:1.5rem;">
        <button disabled="@(CurrentPage <= 1)" @onclick="() => GoToPage(CurrentPage - 1)"
                style="padding:0.5rem 1rem;border:1px solid #ccc;border-radius:4px;background:white;cursor:pointer;">
            Previous
        </button>

        @for (int i = 1; i <= totalPages; i++)
        {
            var pageNum = i;
            <button @onclick="() => GoToPage(pageNum)"
                    style="padding:0.5rem 0.75rem;border:1px solid #ccc;border-radius:4px;background:@(pageNum == CurrentPage ? "#2a7ae2" : "white");color:@(pageNum == CurrentPage ? "white" : "black");cursor:pointer;">
                @pageNum
            </button>
        }

        <button disabled="@(CurrentPage >= totalPages)" @onclick="() => GoToPage(CurrentPage + 1)"
                style="padding:0.5rem 1rem;border:1px solid #ccc;border-radius:4px;background:white;cursor:pointer;">
            Next
        </button>
    </nav>
}

@code {
    [Parameter]
    public int CurrentPage { get; set; }

    [Parameter]
    public int TotalCount { get; set; }

    [Parameter]
    public int PageSize { get; set; }

    [Parameter]
    public EventCallback<int> OnPageChanged { get; set; }

    private async Task GoToPage(int page)
    {
        await OnPageChanged.InvokeAsync(page);
    }
}

@page "/catalog"
@namespace sv_10bfae382c55410eb1802d716e7f5877.Components.Pages.Catalog
@rendermode InteractiveServer
@inject IProductService ProductService

<PageTitle>Product Catalog</PageTitle>

<div style="display:flex;gap:1rem;">
    <!-- Sidebar (25%) -->
    <div style="flex:0 0 25%;min-width:220px;">
        <CatalogSidebar Categories="_categories" OnFilterApplied="HandleFilterApplied" OnFilterCleared="HandleFilterCleared" />
    </div>

    <!-- Main content (75%) -->
    <div style="flex:1;">
        @if (_loading)
        {
            <p><em>Loading products...</em></p>
        }
        else if (_error is not null)
        {
            <div style="color:#dc3545;padding:1rem;border:1px solid #dc3545;border-radius:4px;">
                <strong>Error:</strong> @_error
            </div>
        }
        else if (_result is null || _result.Items.Count == 0)
        {
            <p>No products found matching your criteria.</p>
        }
        else
        {
            <CatalogToolbar SortBy="@_sortBy" TotalCount="_result.TotalCount" Page="_result.Page" PageSize="_result.PageSize" OnSortChanged="HandleSortChanged" />
            <ProductGrid Products="_result.Items" OnProductSelected="HandleProductSelected" OnAddToCart="HandleAddToCart" />
            <CatalogPagination CurrentPage="_currentPage" TotalCount="_result.TotalCount" PageSize="_pageSize" OnPageChanged="HandlePageChanged" />
        }
    </div>
</div>

@code {
    /// <summary>Raised when a product card is clicked so a parent can navigate to the detail page.</summary>
    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    private List<string> _categories = [];
    private PagedResult<Product>? _result;
    private ProductFilter _filter = new(null, null, null, false);
    private string _sortBy = "price_asc";
    private int _currentPage = 1;
    private const int _pageSize = 12;
    private bool _loading = true;
    private string? _error;

    protected override async Task OnInitializedAsync()
    {
        try
        {
            _categories = await ProductService.GetCategoriesAsync();
            await LoadProducts();
        }
        catch (Exception ex)
        {
            _error = ex.Message;
            _loading = false;
        }
    }

    private async Task LoadProducts()
    {
        _loading = true;
        _error = null;
        StateHasChanged();

        try
        {
            _result = await ProductService.SearchAsync(_filter, _sortBy, _currentPage, _pageSize);
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task HandleFilterApplied(ProductFilter filter)
    {
        _filter = filter;
        _currentPage = 1;
        await LoadProducts();
    }

    private async Task HandleFilterCleared()
    {
        _filter = new ProductFilter(null, null, null, false);
        _currentPage = 1;
        await LoadProducts();
    }

    private async Task HandleSortChanged(string sortBy)
    {
        _sortBy = sortBy;
        _currentPage = 1;
        await LoadProducts();
    }

    private async Task HandlePageChanged(int page)
    {
        _currentPage = page;
        await LoadProducts();
    }

    private async Task HandleProductSelected(Product product)
    {
        await OnProductSelected.InvokeAsync(product);
    }

    private Task HandleAddToCart(Product product)
    {
        // Placeholder for cart functionality
        return Task.CompletedTask;
    }
}

